import{_ as t,o as s,c as a,a2 as i}from"./chunks/framework.BS0bAV7E.js";const u=JSON.parse('{"title":"Website update mechanics","description":"","frontmatter":{},"headers":[],"relativePath":"release/website-update.md","filePath":"release/website-update.md"}'),o={name:"release/website-update.md"};function d(n,e,r,l,c,h){return s(),a("div",null,[...e[0]||(e[0]=[i('<h1 id="website-update-mechanics" tabindex="-1">Website update mechanics <a class="header-anchor" href="#website-update-mechanics" aria-label="Permalink to &quot;Website update mechanics&quot;">​</a></h1><p><code>tools/update_website.sh</code> - run at release time after the assets exist. What it does (each step verifiable):</p><ol><li>Reads the three assets from <code>dist/</code>, computes SHA256 + size.</li><li>Regenerates the site&#39;s data file (<code>site.ts</code> constants: RELEASE / ISO / SRC / OTA names + hashes + sizes) from those values - no hand-editing of versions anywhere.</li><li>Regenerates <code>update.json</code> + <code>update-v2.json</code> (version, build, time, changes text, package URL/sha/size) from the manifest template + the release notes.</li><li>Runs the hash gate: the downloads directory&#39;s files must match the constants before anything is pushed.</li><li>Builds the static site and pushes gh-pages.</li></ol><p>Verification after it runs:</p><ul><li><code>https://cubestudio-dev.github.io/OpenCubeOS/update.json</code> shows the new version/build/sha.</li><li>The download page&#39;s three hashes equal the Release&#39;s three.</li><li><code>curl -sL &lt;asset-url&gt; | sha256sum</code> on each asset equals its declared SHA256.</li></ul><p>The script is idempotent per release: rerunning with the same dist/ produces the same pages (deterministic templates).</p>',6)])])}const m=t(o,[["render",d]]);export{u as __pageData,m as default};
